"use client";

import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { CircleCheckIcon } from "../parts/icons";
import { PersonAvatar } from "./shared/person-avatar";
import { useTimeouts } from "./shared/use-timeouts";
import { AGENT, type ChatMessage, DEFAULT_ANSWER, QUICK_REPLIES, THREAD, nextTime } from "./support-conversation/data";
import { MessageBubble } from "./support-conversation/message-bubble";
import { ReplyBox } from "./support-conversation/reply-box";
import { TypingDots } from "./support-conversation/typing-dots";

/**
 * A support thread between a clinic manager and Fernhill support. People
 * reply in their own words or with a quick reply, attach a picture, watch the
 * receipt turn to seen and the agent answer, and resolve or reopen the thread.
 */
export function SupportConversation({ className }: { className?: string }) {
  const [messages, setMessages] = useState<ChatMessage[]>(THREAD);
  const [typing, setTyping] = useState(false);
  const [resolved, setResolved] = useState(false);
  const [used, setUsed] = useState<Set<string>>(new Set());
  const thread = useRef<HTMLDivElement>(null);
  const later = useTimeouts();
  const titleId = useId();

  // Keep the newest message in view as the thread grows.
  useEffect(() => {
    const box = thread.current;
    if (!box) return;
    const smooth = !window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    box.scrollTo({ top: box.scrollHeight, behavior: smooth ? "smooth" : "auto" });
  }, [messages.length, typing]);

  const send = (text: string, attachment?: string) => {
    const id = `m${Date.now()}`;
    const answer = QUICK_REPLIES.find((reply) => reply.text === text)?.answer ?? DEFAULT_ANSWER;
    setMessages((list) => [...list, { id, from: "me", text, attachment, time: nextTime(list.length), receipt: "sent" }]);
    later(() => setMessages((list) => list.map((message) => (message.id === id ? { ...message, receipt: "seen" } : message))), 700);
    later(() => setTyping(true), 1000);
    later(() => {
      setTyping(false);
      setMessages((list) => [...list, { id: `${id}-answer`, from: "agent", text: answer, time: nextTime(list.length) }]);
    }, 2600);
  };

  const quickReply = (text: string) => {
    setUsed((set) => new Set(set).add(text));
    send(text);
  };

  const lastMine = messages.findLastIndex((message) => message.from === "me");
  const replies = QUICK_REPLIES.filter((reply) => !used.has(reply.text));

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
        <div className="flex min-w-0 items-center gap-3">
          <PersonAvatar person={AGENT} size="lg" />
          <div className="min-w-0">
            <h2 id={titleId} className="truncate text-base font-semibold">
              Wrong clinic on Tuesday sessions
            </h2>
            <p className="truncate text-sm text-muted-foreground">
              {AGENT.name}, Fernhill support. Usually replies in 4 minutes
            </p>
          </div>
        </div>
        <Button type="button" variant={resolved ? "outline" : "default"} size="sm" onClick={() => setResolved((value) => !value)}>
          {resolved ? "Reopen" : (
            <>
              <CircleCheckIcon aria-hidden="true" />
              Resolve
            </>
          )}
        </Button>
      </header>

      <div ref={thread} className="scroll-fade-effect-y scrollbar-none h-104 overflow-y-auto px-4 pb-4">
        <div className="flex items-center gap-3 pt-4 text-xs text-muted-foreground" role="separator" aria-label="Today">
          <span className="h-px flex-1 bg-border" />
          Today
          <span className="h-px flex-1 bg-border" />
        </div>
        <ol role="log" aria-label="Messages" aria-live="polite" className="flex flex-col">
          {messages.map((message, index) => (
            <MessageBubble
              key={message.id}
              message={message}
              continued={messages[index - 1]?.from === message.from}
              showReceipt={index === lastMine}
            />
          ))}
        </ol>
        {typing ? (
          <p className="mt-3 ml-10 flex items-center gap-2 text-xs text-muted-foreground">
            <TypingDots />
            {AGENT.short} is writing
          </p>
        ) : null}
        {resolved ? (
          <p role="status" className="mt-4 flex items-center justify-center gap-1.5 text-xs text-marketing-green-ink">
            <CircleCheckIcon aria-hidden="true" className="size-3.5" />
            You marked this resolved
          </p>
        ) : null}
      </div>

      {!resolved && !typing && replies.length > 0 ? (
        <ul aria-label="Quick replies" className="scroll-fade-effect-x scrollbar-none flex gap-2 overflow-x-auto border-t border-border px-3 py-2.5">
          {replies.map((reply) => (
            <li key={reply.text} className="shrink-0">
              <Button type="button" variant="outline" size="sm" onClick={() => quickReply(reply.text)}>
                {reply.text}
              </Button>
            </li>
          ))}
        </ul>
      ) : null}

      <ReplyBox onSend={send} disabled={resolved} disabledReason="Reopen the conversation to reply." />
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

