"use client";

import { useCallback, useEffect, useRef } from "react";

/**
 * Schedules timers that are all cleared when the component unmounts, so a
 * simulated reply never lands on a block that is gone. Returns `later(run, ms)`.
 */
export function useTimeouts() {
  const ids = useRef(new Set<number>());
  useEffect(() => {
    const pending = ids.current;
    return () => {
      for (const id of pending) window.clearTimeout(id);
      pending.clear();
    };
  }, []);
  return useCallback((run: () => void, ms: number) => {
    const id = window.setTimeout(() => {
      ids.current.delete(id);
      run();
    }, ms);
    ids.current.add(id);
    return id;
  }, []);
}

import { PEOPLE } from "../shared/people";

/** One message in the thread. */
export interface ChatMessage {
  id: string;
  from: "agent" | "me";
  text: string;
  time: string;
  /** For the viewer's own messages: whether the agent has read it yet. */
  receipt?: "sent" | "seen";
  /** A button under an agent message that takes the viewer somewhere. */
  action?: string;
  /** The file name of an attached picture. */
  attachment?: string;
}

/** The support agent on the thread. */
export const AGENT = PEOPLE.priya;

/** The viewer, a clinic manager. */
export const ME = PEOPLE.lena;

/** The thread so far. */
export const THREAD: ChatMessage[] = [
  { id: "c1", from: "me", text: "Hi, since this morning our Tuesday sessions show Mill Lane instead of Harbour Street. Patients are getting the wrong address in their reminders.", time: "09:12", receipt: "seen" },
  { id: "c2", from: "agent", text: "Thanks Lena, I can see it. Last night the sessions were copied from the Mill Lane template, so they took its address.", time: "09:15" },
  { id: "c3", from: "agent", text: "I have moved all 14 Tuesday sessions back to Harbour Street, and reminders sent from now on carry the right address. Could you check that they look right?", time: "09:16", action: "Open Tuesday sessions" },
];

/** The quick replies, each with the answer the agent sends back. */
export const QUICK_REPLIES: { text: string; answer: string }[] = [
  { text: "They look right now", answer: "Great. I have also added a check so a template copy can never change a clinic's address again." },
  { text: "Two still show Mill Lane", answer: "Thanks for spotting that. The 16:00 and 16:30 sessions had their own override. Both are fixed now." },
  { text: "Can you resend the reminders?", answer: "Done. The 23 patients booked for Tuesday got a corrected reminder a moment ago." },
];

/** What the agent says to any reply that is not a quick reply. */
export const DEFAULT_ANSWER = "Thanks, I am on it. I will reply here within a few minutes.";

/** The time stamp for a new message: the thread runs on from 09:20, one minute a message. */
export function nextTime(count: number) {
  const minutes = 9 * 60 + 17 + count;
  return `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`;
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { CheckIcon, ChevronRightIcon } from "../../parts/icons";
import { PaperclipIcon, ReadIcon } from "../icons";
import { PersonAvatar } from "../shared/person-avatar";
import { AGENT, type ChatMessage, ME } from "./data";

/** Props for one message in the thread. */
export interface MessageBubbleProps {
  message: ChatMessage;
  /** Hides the name and avatar when the same person sent the message just before. */
  continued: boolean;
  /** Shows the read receipt, which only the viewer's latest message carries. */
  showReceipt: boolean;
}

/**
 * One message. The agent's sit on the left with an avatar, the viewer's on
 * the right in the primary colour. A new message rises in on a soft spring.
 */
export function MessageBubble({ message, continued, showReceipt }: MessageBubbleProps) {
  const reduceMotion = useReducedMotion();
  const mine = message.from === "me";
  const person = mine ? ME : AGENT;

  return (
    <motion.li
      layout={reduceMotion ? false : "position"}
      initial={reduceMotion ? false : { opacity: 0, y: 14, scale: 0.98 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      transition={{ type: "spring", stiffness: 360, damping: 30 }}
      className={cn("flex gap-2.5", mine ? "flex-row-reverse" : "flex-row", continued ? "mt-1" : "mt-4")}
    >
      <span className="w-8 shrink-0">{!mine && !continued ? <PersonAvatar person={person} /> : null}</span>
      <div className={cn("flex max-w-[85%] min-w-0 flex-col gap-1 @lg:max-w-[70%]", mine ? "items-end" : "items-start")}>
        {!continued ? (
          <p className="text-xs text-muted-foreground">
            <span className="font-medium text-foreground">{mine ? "You" : person.name}</span> {message.time}
          </p>
        ) : (
          <span className="sr-only">
            {mine ? "You" : person.name}, {message.time}
          </span>
        )}
        <div
          className={cn(
            "rounded-2xl px-3.5 py-2 text-sm",
            mine ? "rounded-tr-md bg-primary text-primary-foreground" : "rounded-tl-md border border-border bg-background text-foreground",
          )}
        >
          {message.text}
          {message.attachment ? (
            <span className={cn("mt-2 flex items-center gap-1.5 rounded-lg px-2 py-1 text-xs", mine ? "bg-primary-foreground/15" : "bg-muted")}>
              <PaperclipIcon aria-hidden="true" className="size-3.5" />
              {message.attachment}
            </span>
          ) : null}
        </div>
        {message.action ? (
          <Button type="button" variant="outline" size="sm">
            {message.action}
            <ChevronRightIcon aria-hidden="true" className="size-3.5" />
          </Button>
        ) : null}
        {mine && showReceipt && message.receipt ? (
          <span className="flex items-center gap-1 text-xs text-muted-foreground">
            {message.receipt === "seen" ? <ReadIcon aria-hidden="true" className="size-3.5 text-chart-1" /> : <CheckIcon aria-hidden="true" className="size-3.5" />}
            {message.receipt === "seen" ? `Seen by ${AGENT.short}` : "Sent"}
          </span>
        ) : null}
      </div>
    </motion.li>
  );
}

