"use client";

import { type FormEvent, type KeyboardEvent, useId, useState } from "react";

import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

import { XIcon } from "../../parts/icons";
import { PaperclipIcon, SendIcon } from "../icons";

/** Props for the reply field. */
export interface ReplyBoxProps {
  onSend: (text: string, attachment?: string) => void;
  disabled: boolean;
  /** Says why the field is off, such as "Reopen the conversation to reply." */
  disabledReason?: string;
}

const SAMPLE_FILE = "tuesday-sessions.png";

/**
 * The reply field with attach and send. Enter sends, Shift and Enter starts a
 * new line. Attach adds a sample picture the viewer can remove before sending.
 */
export function ReplyBox({ onSend, disabled, disabledReason }: ReplyBoxProps) {
  const [text, setText] = useState("");
  const [attachment, setAttachment] = useState<string | undefined>(undefined);
  const fieldId = useId();
  const reasonId = useId();
  const ready = !disabled && (text.trim().length > 0 || attachment !== undefined);

  const send = (event?: FormEvent) => {
    event?.preventDefault();
    if (!ready) return;
    onSend(text.trim() || "Here is a picture.", attachment);
    setText("");
    setAttachment(undefined);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing && event.keyCode !== 229) send(event);
  };

  return (
    <form onSubmit={send} className="flex flex-col gap-2 border-t border-border p-3">
      {attachment ? (
        <span className="flex w-max max-w-full items-center gap-1.5 rounded-lg border border-border py-1 pr-1 pl-2 text-xs">
          <PaperclipIcon aria-hidden="true" className="size-3.5 text-muted-foreground" />
          <span className="truncate">{attachment}</span>
          <Button type="button" variant="ghost" size="icon" className="size-6" aria-label={`Remove ${attachment}`} onClick={() => setAttachment(undefined)}>
            <XIcon aria-hidden="true" className="size-3.5" />
          </Button>
        </span>
      ) : null}
      <div className="flex items-end gap-2">
        <Button
          type="button"
          variant="ghost"
          size="icon"
          aria-label="Attach a picture"
          disabled={disabled || attachment !== undefined}
          onClick={() => setAttachment(SAMPLE_FILE)}
        >
          <PaperclipIcon aria-hidden="true" />
        </Button>
        <label htmlFor={fieldId} className="sr-only">
          Reply to Fernhill support
        </label>
        <Textarea
          id={fieldId}
          value={text}
          onChange={(event) => setText(event.target.value)}
          onKeyDown={onKeyDown}
          disabled={disabled}
          aria-describedby={disabled ? reasonId : undefined}
          placeholder={disabled ? disabledReason : "Write a reply"}
          rows={1}
          className="max-h-32 min-h-9 resize-none"
        />
        <Button type="submit" size="icon" aria-label="Send" disabled={!ready}>
          <SendIcon aria-hidden="true" />
        </Button>
      </div>
      {disabled ? (
        <p id={reasonId} className="sr-only">
          {disabledReason}
        </p>
      ) : null}
    </form>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

/**
 * Three dots that brighten in turn while the agent writes. Under reduced
 * motion they hold still; the words beside them say the same thing.
 */
export function TypingDots({ className }: { className?: string }) {
  const reduceMotion = useReducedMotion();
  return (
    <span aria-hidden="true" className={cn("inline-flex items-center gap-1", className)}>
      {[0, 1, 2].map((dot) => (
        <motion.span
          key={dot}
          animate={reduceMotion ? undefined : { opacity: [0.3, 1, 0.3] }}
          transition={{ duration: 1, repeat: Infinity, delay: dot * 0.18, ease: "easeInOut" }}
          className="size-1.5 rounded-full bg-current"
        />
      ))}
    </span>
  );
}
